// 堆疊：遇到數字入棧，遇到運算子彈出兩個運算
// 時間複雜度: O(n)，空間複雜度: O(n)
function evalRPN(tokens) {
    const stack = [];
    for (const t of tokens) {
        if (t === '+' || t === '-' || t === '*' || t === '/') {
            const b = stack.pop(); // 注意順序：先彈出的是右運算元
            const a = stack.pop();
            if (t === '+')
                stack.push(a + b);
            else if (t === '-')
                stack.push(a - b);
            else if (t === '*')
                stack.push(a * b);
            else
                stack.push(Math.trunc(a / b)); // 向零取整
        }
        else {
            stack.push(Number(t));
        }
    }
    return stack[0];
}

