class Solution:
    def evalRPN(self, tokens: List[str]) -> int:
        stack = []
        operators = {'+', '-', '*', '/'}

        for token in tokens:
            if token in operators:
                b = stack.pop()      # 先彈出的是【右】運算元
                a = stack.pop()      # 後彈出的是【左】運算元

                if token == '+':
                    stack.append(a + b)
                elif token == '-':
                    stack.append(a - b)
                elif token == '*':
                    stack.append(a * b)
                else:
                    # Python 的 // 是向下取整，這裡要向零截斷
                    stack.append(int(a / b))
            else:
                stack.append(int(token))   # 注意：可能是負數如 "-11"

        return stack[0]


# 用字典 + lambda 讓程式碼更簡潔
class Solution:
    def evalRPN(self, tokens: List[str]) -> int:
        ops = {
            '+': lambda a, b: a + b,
            '-': lambda a, b: a - b,
            '*': lambda a, b: a * b,
            '/': lambda a, b: int(a / b),    # 向零截斷
        }
        stack = []
        for token in tokens:
            if token in ops:
                b, a = stack.pop(), stack.pop()
                stack.append(ops[token](a, b))
            else:
                stack.append(int(token))
        return stack[0]

