class Solution {
public:
    int evalRPN(vector<string>& tokens) {
        stack<long long> stk;

        for (const string& token : tokens) {
            if (token == "+" || token == "-" ||
                token == "*" || token == "/") {
                long long b = stk.top(); stk.pop();   // 右運算元
                long long a = stk.top(); stk.pop();   // 左運算元

                if      (token == "+") stk.push(a + b);
                else if (token == "-") stk.push(a - b);
                else if (token == "*") stk.push(a * b);
                else                   stk.push(a / b);  // C++ 本來就向零截斷
            } else {
                stk.push(stoll(token));    // stoll 可正確處理負號
            }
        }
        return (int)stk.top();
    }
};

